  const fs = require('node:fs');
  const path = require('node:path');
  const crypto = require('node:crypto');
  const { repo, stage, baseUrl = 'https://dunkbin.com' } = config;
  if (!stage.startsWith(path.join(repo, 'n8n-staging') + path.sep)) throw new Error('Invalid staging path');
  // Keep the API payload in a file so catalog growth cannot exceed shell argument limits.
  const images = config.images ?? JSON.parse(fs.readFileSync(path.join(stage, 'images.json'), 'utf8'))[0].images;
  if (!Array.isArray(images) || !images.length) throw new Error('Empty or invalid image manifest');
