  const files = [];
  let cursor = 0;
  const seen = new Set();
  for (const item of images) {
    if (!Number.isSafeInteger(item.id) || item.id <= 0 || !/^[a-f0-9]{32}$/.test(item.md5) || seen.has(item.id)) {
      throw new Error('Invalid or duplicate cosmetic id/hash');
    }
    seen.add(item.id);
  }
