    while (cursor < images.length) {
      const item = images[cursor++];
      const file = 'public/img/' + item.id + '.png';
      const target = path.join(repo, file);
      if (fs.existsSync(target) && md5(fs.readFileSync(target)) === item.md5) continue;
      let bytes;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const response = await fetch(baseUrl + '/img/' + item.id + '-' + item.md5 + '.png', {
            redirect: 'error', signal: AbortSignal.timeout(30000),
          });
          if (!response.ok) throw new Error('Image HTTP ' + response.status);
          if (Number(response.headers.get('content-length')) > 25 * 1024 * 1024) throw new Error('Image too large');
          bytes = Buffer.from(await response.arrayBuffer());
          if (bytes.length > 25 * 1024 * 1024 || bytes.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a') throw new Error('Invalid PNG response');
          if (md5(bytes) !== item.md5) throw new Error('Downloaded image hash does not match API');
          break;
        } catch (error) {
          if (attempt === 2) throw new Error('Cosmetic ' + item.id + ': ' + error.message);
          await new Promise(resolve => setTimeout(resolve, (attempt + 1) * 1000));
        }
      }
      fs.writeFileSync(path.join(stage, file), bytes, { flag: 'wx' });
      files.push(file);
    }
  }
  // Wait for all workers to stop before reporting failure; no background writes outlive this operation.
  const results = await Promise.allSettled(Array.from({ length: Math.min(4, images.length) }, worker));
